typedef long long ll;

typedef struct {
    int x, y;
} Fountain;

typedef struct {
    int key;
    int id;
} Pair;

typedef struct {
    ll dist;
    int v;
} HeapNode;

static int cmp_pair_key(const void *a, const void *b) {
    const Pair *pa = (const Pair *)a;
    const Pair *pb = (const Pair *)b;
    if (pa->key < pb->key) return -1;
    if (pa->key > pb->key) return 1;
    return 0;
}

static int lower_bound_pairs(Pair *arr, int n, int key) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (arr[m].key < key) l = m + 1;
        else r = m;
    }
    return l;
}

static int find_id(Pair *arr, int n, int key) {
    int p = lower_bound_pairs(arr, n, key);
    if (p < n && arr[p].key == key) return arr[p].id;
    return -1;
}

static ll iabsll(ll x) { return x < 0 ? -x : x; }

static ll manhattan100(int x1, int y1, int x2, int y2) {
    return 100LL * (iabsll((ll)x1 - x2) + iabsll((ll)y1 - y2));
}

/*
Movement model:
- Streets/avenues are normal paths.
- A fountain occupies an intersection and blocks direct crossing there,
  but one may move along its perimeter.
- Since every street and every avenue has at most one fountain, each fountain
  can only interact with nearest fountains in x-order and y-order.
- Build graph on fountains + source + target.
  Edge between neighboring fountains in same street-order or avenue-order:
    cost = 100 * min(|dx|, |dy|)
  Edge from source/target point to every fountain:
    cost = 100 * min(|dx|, |dy|)
  Direct source-target:
    Manhattan distance * 100
Then shortest path gives answer.
*/

typedef struct {
    int to;
    ll w;
    int next;
} Edge;

static void add_edge(Edge *edges, int *head, int *ecnt, int u, int v, ll w) {
    edges[*ecnt].to = v;
    edges[*ecnt].w = w;
    edges[*ecnt].next = head[u];
    head[u] = (*ecnt)++;
}

static void heap_push(HeapNode *heap, int *sz, HeapNode val) {
    int i = ++(*sz);
    while (i > 1) {
        int p = i >> 1;
        if (heap[p].dist <= val.dist) break;
        heap[i] = heap[p];
        i = p;
    }
    heap[i] = val;
}

static HeapNode heap_pop(HeapNode *heap, int *sz) {
    HeapNode ret = heap[1];
    HeapNode last = heap[(*sz)--];
    int i = 1;
    while ((i << 1) <= *sz) {
        int l = i << 1, r = l + 1, c = l;
        if (r <= *sz && heap[r].dist < heap[l].dist) c = r;
        if (heap[c].dist >= last.dist) break;
        heap[i] = heap[c];
        i = c;
    }
    heap[i] = last;
    return ret;
}

