    qsort(byX, N, sizeof(Pair), cmp_pair_key);
    qsort(byY, N, sizeof(Pair), cmp_pair_key);

    int V = N + 2;
    int S = N, T = N + 1;

    /* Enough edges:
       - between consecutive in x: 2*(N-1)
       - between consecutive in y: 2*(N-1)
       - source to all fountains and back: 2N
       - target to all fountains and back: 2N
       - source-target both ways: 2
    */
    int maxE = 8 * N + 10;
    Edge *edges = (Edge *)malloc((size_t)maxE * sizeof(Edge));
    int *head = (int *)malloc((size_t)V * sizeof(int));
    for (int i = 0; i < V; ++i) head[i] = -1;
    int ecnt = 0;

    for (int i = 0; i + 1 < N; ++i) {
        int a = byX[i].id, b = byX[i + 1].id;
        ll w = 100LL * (ll)(f[b].x - f[a].x);
        add_edge(edges, head, &ecnt, a, b, w);
        add_edge(edges, head, &ecnt, b, a, w);
    }
    for (int i = 0; i + 1 < N; ++i) {
        int a = byY[i].id, b = byY[i + 1].id;
        ll w = 100LL * (ll)(f[b].y - f[a].y);
        add_edge(edges, head, &ecnt, a, b, w);
        add_edge(edges, head, &ecnt, b, a, w);
    }

    for (int i = 0; i < N; ++i) {
        ll ws = 100LL * (ll)((iabsll((ll)f[i].x - x1) < iabsll((ll)f[i].y - y1)) ?
                              iabsll((ll)f[i].x - x1) : iabsll((ll)f[i].y - y1));
        ll wt = 100LL * (ll)((iabsll((ll)f[i].x - x2) < iabsll((ll)f[i].y - y2)) ?
                              iabsll((ll)f[i].x - x2) : iabsll((ll)f[i].y - y2));
        add_edge(edges, head, &ecnt, S, i, ws);
        add_edge(edges, head, &ecnt, i, S, ws);
        add_edge(edges, head, &ecnt, T, i, wt);
        add_edge(edges, head, &ecnt, i, T, wt);
    }

    ll direct = manhattan100(x1, y1, x2, y2);
    add_edge(edges, head, &ecnt, S, T, direct);
    add_edge(edges, head, &ecnt, T, S, direct);

    ll INF = (1LL << 62);
    ll *dist = (ll *)malloc((size_t)V * sizeof(ll));
    char *used = (char *)calloc((size_t)V, 1);
    for (int i = 0; i < V; ++i) dist[i] = INF;
    dist[S] = 0;

    HeapNode *heap = (HeapNode *)malloc((size_t)(maxE + V + 10) * sizeof(HeapNode));
    int hsz = 0;
    heap_push(heap, &hsz, (HeapNode){0, S});

    while (hsz > 0) {
        HeapNode cur = heap_pop(heap, &hsz);
        int v = cur.v;
        if (used[v]) continue;
        used[v] = 1;
        if (v == T) break;

        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            ll nd = dist[v] + edges[e].w;
            if (nd < dist[to]) {
                dist[to] = nd;
                heap_push(heap, &hsz, (HeapNode){nd, to});
            }
        }
    }

    printf("%lld\n", dist[T]);

    free(f);
    free(byX);
    free(byY);
    free(edges);
    free(head);
    free(dist);
    free(used);
    free(heap);

    return 0;
}

