#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 62);

struct Node {
    int x, y;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    int x1, y1, x2, y2;
    cin >> N;
    vector<Node> f(N);
    for (int i = 0; i < N; ++i) cin >> f[i].x >> f[i].y;
    cin >> x1 >> y1 >> x2 >> y2;

    // Build fountain index by avenue and by street.
    unordered_map<int, int> byX, byY;
    byX.reserve(N * 2 + 10);
    byY.reserve(N * 2 + 10);
    for (int i = 0; i < N; ++i) {
        byX[f[i].x] = i;
        byY[f[i].y] = i;
    }

    // Graph:
    // 0..N-1 : fountains
    // N      : start
    // N+1    : target
    int S = N, T = N + 1;
    vector<vector<pair<int,int>>> g(N + 2);

    auto add_edge = [&](int u, int v, int w) {
        g[u].push_back({v, w});
        g[v].push_back({u, w});
    };

    // Between fountains:
    // Since each avenue/street has at most one fountain, from a fountain you can
    // move along its perimeter to any point on the same avenue or street with an
    // effective saving of 20 meters compared to pure grid walk.
    // Thus between two fountains sharing x or y:
    // cost = 100 * manhattan - 20.
    for (int i = 0; i < N; ++i) {
        auto itx = byX.find(f[i].x);
        if (itx != byX.end()) {
            int j = itx->second;
            if (j != i) {
                ll d = 100LL * (ll)abs(f[i].y - f[j].y) - 20;
                add_edge(i, j, (int)d);
            }
        }
        auto ity = byY.find(f[i].y);
        if (ity != byY.end()) {
            int j = ity->second;
            if (j != i) {
                ll d = 100LL * (ll)abs(f[i].x - f[j].x) - 20;
                add_edge(i, j, (int)d);
            }
        }
    }

    // Actually above self-maps are trivial; we need all fountain pairs that share x or y.
    // Because each x and each y has at most one fountain, no two different fountains share x or y.
    // Therefore there are no direct fountain-fountain special edges.
    // The useful edges are only from start/target to fountains, and direct start-target.
    // We'll keep the graph simple below.

    g.assign(N + 2, {});

    auto manhattan_cost = [&](int ax, int ay, int bx, int by) -> ll {
        return 100LL * (ll)(abs(ax - bx) + abs(ay - by));
    };

    // Direct path start -> target
    add_edge(S, T, (int)manhattan_cost(x1, y1, x2, y2));

    // From a point to a fountain:
    // If sharing x or y, can touch fountain perimeter and save 10 meters.
    // Otherwise no benefit over ordinary Manhattan path.
    auto point_to_fountain = [&](int px, int py, int fx, int fy) -> ll {
        ll base = manhattan_cost(px, py, fx, fy);
        if (px == fx || py == fy) return base - 10;
        return base;
    };

    for (int i = 0; i < N; ++i) {
        add_edge(S, i, (int)point_to_fountain(x1, y1, f[i].x, f[i].y));
        add_edge(T, i, (int)point_to_fountain(x2, y2, f[i].x, f[i].y));
    }

    // Between fountains:
    // Enter first fountain perimeter (-10), move between tangent exit/entry points,
    // and enter second fountain perimeter (-10) if they share avenue or street.
    // Otherwise no improvement over Manhattan.
    auto fountain_to_fountain = [&](int i, int j) -> ll {
        ll base = manhattan_cost(f[i].x, f[i].y, f[j].x, f[j].y);
        if (f[i].x == f[j].x || f[i].y == f[j].y) return base - 20;
        return base;
    };

    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            add_edge(i, j, (int)fountain_to_fountain(i, j));
        }
    }

    // Dijkstra
    vector<ll> dist(N + 2, INF);
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
    dist[S] = 0;
    pq.push({0, S});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue;
        if (u == T) break;
        for (auto [v, w] : g[u]) {
            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }

    cout << dist[T] << '\n';
    return 0;
}

