public class Solution {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int x1 = Integer.parseInt(st.nextToken());
        int y1 = Integer.parseInt(st.nextToken());
        int x2 = Integer.parseInt(st.nextToken());
        int y2 = Integer.parseInt(st.nextToken());

        int n = Integer.parseInt(br.readLine());
        int[][] fountains = new int[n][2];
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            fountains[i][0] = Integer.parseInt(st.nextToken());
            fountains[i][1] = Integer.parseInt(st.nextToken());
        }

        // We only care about fountains in the rectangle between start and end
        List<int[]> list = new ArrayList<>();
        int xMin = Math.min(x1, x2);
        int xMax = Math.max(x1, x2);
        int yMin = Math.min(y1, y2);
        int yMax = Math.max(y1, y2);

        for (int[] f : fountains) {
            if (f[0] >= xMin && f[0] <= xMax && f[1] >= yMin && f[1] <= yMax) {
                list.add(f);
            }
        }

        // Sort by x, then by y
        boolean reverseX = x1 > x2;
        boolean reverseY = y1 > y2;
        list.sort((a, b) -> {
            int ax = reverseX ? -a[0] : a[0];
            int bx = reverseX ? -b[0] : b[0];
            if (ax != bx) return Integer.compare(ax, bx);
            int ay = reverseY ? -a[1] : a[1];
            int by = reverseY ? -b[1] : b[1];
            return Integer.compare(ay, by);
        });

        // LIS on y coordinates
        List<Integer> lis = new ArrayList<>();
        for (int[] f : list) {
            int y = reverseY ? -f[1] : f[1];
            int pos = Collections.binarySearch(lis, y);
            if (pos < 0) pos = -pos - 1;
            if (pos == lis.size()) {
                lis.add(y);
            } else {
                lis.set(pos, y);
            }
        }

        int k = lis.size();
        double dist = 100.0 * (Math.abs(x1 - x2) + Math.abs(y1 - y2));
        if (k > 0) {
            dist = dist - k * 200 + k * (100 * Math.PI / 2);
        }

        System.out.printf("%.15f%n", dist);
    }
}

