    ans = 100*(dx+dy) - (20 - 5*pi)*(L-1) - (20 - 10*pi)
 else
    ans = 100*(dx+dy) - (20 - 5*pi)*L

This is the known formula from AtCoder ARC 087 D / ABC? Let's implement this established solution.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Pair {
        int x, y;
        Pair(int x, int y) { this.x = x; this.y = y; }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int x1 = fs.nextInt();
        int y1 = fs.nextInt();
        int x2 = fs.nextInt();
        int y2 = fs.nextInt();

        int lx = Math.min(x1, x2), rx = Math.max(x1, x2);
        int ly = Math.min(y1, y2), ry = Math.max(y1, y2);

        int sx = x1 <= x2 ? 1 : -1;
        int sy = y1 <= y2 ? 1 : -1;

        ArrayList<Pair> list = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            if (lx <= x && x <= rx && ly <= y && y <= ry) {
                list.add(new Pair(x, y));
            }
        }

        // Transform so that both coordinates should increase.
        for (Pair p : list) {
            if (sx == -1) p.x = -p.x;
            if (sy == -1) p.y = -p.y;
        }

        list.sort((a, b) -> {
            if (a.x != b.x) return Integer.compare(a.x, b.x);
            return Integer.compare(a.y, b.y);
        });

        // LIS on y (strictly increasing). Since all original y are distinct among fountains,
        // lower_bound is enough.
        int[] dp = new int[list.size()];
        int lis = 0;
        for (Pair p : list) {
            int pos = Arrays.binarySearch(dp, 0, lis, p.y);
            if (pos < 0) pos = -pos - 1;
            dp[pos] = p.y;
            if (pos == lis) lis++;
        }

        int dx = Math.abs(x2 - x1);
        int dy = Math.abs(y2 - y1);
        int m = Math.min(dx, dy);

        double ans = 100.0 * (dx + dy);
        double PI = Math.PI;

        if (lis == m + 1) {
            ans -= (20.0 - 5.0 * PI) * (lis - 1);
            ans -= (20.0 - 10.0 * PI);
        } else {
            ans -= (20.0 - 5.0 * PI) * lis;
        }

        System.out.printf(Locale.US, "%.15f%n", ans);
    }
}
